import {relayBase} from './online-config.js';
import * as MP from './multiplayer.js';
const encode=async s=>{const stream=new Blob([JSON.stringify(s)]).stream().pipeThrough(new CompressionStream('gzip'));const bytes=new Uint8Array(await new Response(stream).arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=16384)text+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(text);};
const decode=async text=>{const bytes=Uint8Array.from(atob(text),x=>x.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text());};
export class OnlineClient{
 constructor({save,onState,onStatus,onError}){Object.assign(this,{save,onState,onStatus,onError,state:null,room:null,key:null,actor:null,presence:[],running:false,queue:Promise.resolve(),ack:0,sentRevision:-1,feedback:{},lastTicks:{}});}
 get host(){return this.actor==='t0';}
 async request(path='',method='GET',data){const r=await fetch(this.base+'/api/rooms'+path,{method,headers:{'Content-Type':'application/json',...(this.key?{Authorization:'Bearer '+this.key}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(12000)});let result;try{result=await r.json();}catch{throw Error('Le service de connexion ne répond pas.');}if(!r.ok)throw Error(result.error||'Connexion indisponible.');return result;}
 async openHost(state){this.stop();await this.queue;this.base=relayBase(location.href);this.actor='t0';this.key=state.online.keys.t0;this.state=MP.resetSession(state);const allowed=state.online.phase==='lobby'?Object.keys(state.online.keys):state.online.members.map(m=>m.teamId);const result=await this.request('','POST',{keys:Object.fromEntries(allowed.map(id=>[id,state.online.keys[id]]))});this.room=result.room;this.presence=['t0'];this.running=true;await this.save(this.state);this.savedRevision=this.state.online.revision;await this.publish();this.emit();this.poll();this.timer=setInterval(()=>this.clock(),250);}
 async join(invite){this.stop();await this.queue;if(!invite||!/^t[1-5]$/.test(invite.actor)||typeof invite.key!=='string'||!/^https?:$/.test(new URL(invite.base).protocol))throw Error('Invitation invalide.');this.base=invite.base;this.room=invite.room;this.key=invite.key;this.actor=invite.actor;this.state=null;this.running=true;await this.pull();this.poll();}
 invitation(actor){const u=new URL(location.href);u.hash='online='+encodeURIComponent(JSON.stringify({base:this.base,room:this.room,actor,key:this.state.online.keys[actor]}));return u.href;}
 emit(){if(this.state)this.onState(this.state,this.actor,this.presence);this.onStatus(this);}
 enqueue(fn){this.queue=this.queue.then(fn).catch(e=>this.onError(e.message));return this.queue;}
 async apply(actor,cmd){try{const next=MP.command(this.state,actor,cmd,this.presence);if(next===this.state)return;this.state=next;this.state.online.feedback??={};this.state.online.feedback[actor]={id:cmd.id,ok:true};}catch(e){this.state.online.feedback??={};this.state.online.feedback[actor]={id:cmd.id,error:e.message};this.state.online.receipts.push({id:cmd.id,actor});this.state.online.receipts=this.state.online.receipts.slice(-2000);this.state.online.revision++;if(actor===this.actor)this.onError(e.message);}this.emit();await this.save(this.state);this.savedRevision=this.state.online.revision;}
 async send(type,args={}){if(!this.running)throw Error('Ouvrez une session multijoueur.');const cmd={id:crypto.randomUUID(),type,args};if(this.host)return this.enqueue(async()=>{await this.apply(this.actor,cmd);await this.publish();});return this.request('/'+this.room+'/commands','POST',cmd);}
 async publish(){if(!this.host||!this.state)return;const state=this.state,revision=state.online.revision;if(this.savedRevision!==revision){await this.save(state);this.savedRevision=revision;}const allowed=state.online.phase==='lobby'?Object.keys(state.online.keys):state.online.members.map(m=>m.teamId);await this.request('/'+this.room+'/snapshot','POST',{snapshot:await encode(MP.publicState(state)),revision,ack:this.ack,allowed});this.sentRevision=revision;}
 async pull(){const generation=this.generation;const r=await this.request('/'+this.room+'?since='+(this.state?.online.revision??-2));if(!this.running||this.generation!==generation)return;if(r.actor!==this.actor)throw Error('Invitation invalide.');const changed=this.presence.join()!==r.presence.join();this.presence=r.presence;
  if(this.host){for(const c of r.commands||[]){await this.apply(c.actor,c.command);this.ack=Math.max(this.ack,c.seq);}if(this.sentRevision!==this.state.online.revision||(r.commands||[]).length)await this.publish();if(changed)this.emit();}
  else {if(r.snapshot){const next=await decode(r.snapshot);if(!this.running||this.generation!==generation)return;MP.validateOnline(next);this.state=next;const f=next.online.feedback?.[this.actor];if(f&&this.feedback[this.actor]!==f.id){this.feedback[this.actor]=f.id;if(f.error)this.onError(f.error);}this.emit();}else if(changed)this.emit();}
  this.lastSuccess=Date.now();this.onStatus(this);
 }
 async poll(){if(!this.running)return;const generation=this.generation;try{await this.enqueue(async()=>{try{await this.pull();}catch(e){if(Date.now()-(this.lastSuccess||0)>10000){this.presence=[];this.emit();}throw e;}});}finally{if(this.running&&this.generation===generation)this.pollTimer=setTimeout(()=>this.poll(),this.state&&MP.liveFor(this.state,this.actor)?400:1000);}}
 clock(){if(!this.running||!this.host||this.clockBusy)return;this.clockBusy=true;this.enqueue(async()=>{try{if(!this.running)return;const now=Date.now(),due=Object.entries(this.state.online.controls).filter(([id,c])=>c.playing&&now-(this.lastTicks[id]||0)>=c.speed).map(([id])=>id);const next=MP.tick(this.state,this.presence,due);for(const id of due)this.lastTicks[id]=now;if(next!==this.state){this.state=next;this.emit();await this.save(this.state);this.savedRevision=this.state.online.revision;await this.publish();}}finally{this.clockBusy=false;}});}
 stop(){this.generation=(this.generation||0)+1;this.running=false;clearTimeout(this.pollTimer);clearInterval(this.timer);this.presence=[];this.ack=0;this.sentRevision=-1;this.clockBusy=false;this.lastTicks={};this.feedback={};this.lastSuccess=0;this.savedRevision=-1;}
 async leave(){const active=this.running;this.stop();await this.queue;if(active){try{await this.request('/'+this.room+'/leave','POST',{});}catch{}}}
}
export function readInvitation(){try{const p=new URLSearchParams(location.hash.slice(1));const raw=p.get('online');return raw?JSON.parse(raw):null;}catch{return null;}}
